describe('Loading Skeleton During API Data Fetch', () => {
  beforeEach(() => {
    cy.visit('/data-fetch');
  });

  it('should display loading skeleton while API data is being fetched', () => {
    // Intercept the API call
    cy.intercept('GET', '/api/data').as('fetchData');

    // Verify loading skeleton is visible
    cy.get('[data-testid="loading-skeleton"]').should('be.visible');
    cy.get('[data-testid="loading-skeleton"]').should('contain', 'Loading...');

    // Click the button to trigger API call
    cy.get('[data-testid="fetch-data-button"]').click();

    // Wait for the API call to complete
    cy.wait('@fetchData');

    // Verify loading skeleton is hidden
    cy.get('[data-testid="loading-skeleton"]').should('not.exist');

    // Verify data is displayed
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="data-row"]').should('have.length.greaterThan', 0);
  });

  it('should handle API failure and display error message while loading skeleton', () => {
    // Intercept the API call with a 500 error
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('fetchDataError');

    // Verify loading skeleton is visible
    cy.get('[data-testid="loading-skeleton"]').should('be.visible');

    // Click the button to trigger API call
    cy.get('[data-testid="fetch-data-button"]').click();

    // Wait for the API call to complete
    cy.wait('@fetchDataError');

    // Verify loading skeleton is still visible
    cy.get('[data-testid="loading-skeleton"]').should('be.visible');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load data');

    // Verify data table is not displayed
    cy.get('[data-testid="data-table"]').should('not.exist');
  });
});
